+  });
+
+  it('should encrypt sensitive string fields', () => {
+    const obj = {
+      username: 'john',
+      api_key: 'secret-key-123',
+    };
+
+    const result = encryptSensitiveFields(obj, service);
+
+    expect(result.username).toBe('john');
