+      const arrayCache = new CacheService<string[]>();
+      arrayCache.set('arr', ['a', 'b', 'c']);
+      expect(arrayCache.get('arr')).toEqual(['a', 'b', 'c']);
+    });
+  });
+});
+
+describe('Global cache functions', () => {
+  afterEach(() => {
+    clearAllCaches();
+  });
+
+  describe('getCache', () => {
